import{_ as e,o as p,c as r,ac as l}from"./chunks/framework.B-3EzaJq.js";const c=JSON.parse('{"title":"中共中央纪律检查委员会向党的第十二次全国代表大会的工作报告","description":"","frontmatter":{"prev":{"text":"中国共产党第十二次全国代表大会主席团致杨秀峰同志的信","link":"./中国共产党第十二次全国代表大会主席团致杨秀峰同志的信"},"next":{"text":"中国共产党第十二次全国代表大会关于中央纪律检查委员会工作报告的决议","link":"./中国共产党第十二次全国代表大会关于中央纪律检查委员会工作报告的决议"}},"headers":[],"relativePath":"12/中央纪律检查委员会向党的第十二次全国代表大会的工作报告.md","filePath":"12/中央纪律检查委员会向党的第十二次全国代表大会的工作报告.md"}'),i={name:"12/中央纪律检查委员会向党的第十二次全国代表大会的工作报告.md"};function t(h,a,o,n,d,s){return p(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="中共中央纪律检查委员会向党的第十二次全国代表大会的工作报告" tabindex="-1">中共中央纪律检查委员会向党的第十二次全国代表大会的工作报告 <a class="header-anchor" href="#中共中央纪律检查委员会向党的第十二次全国代表大会的工作报告" aria-label="Permalink to &quot;中共中央纪律检查委员会向党的第十二次全国代表大会的工作报告&quot;">​</a></h1><p><em>（一九八二年九月十一日）</em></p><nav class="table-of-contents"><ul><li><a href="#三年多来的主要工作">三年多来的主要工作</a><ul><li><a href="#一、制定和贯彻《关于党内政治生活的若干准则》-端正党风">一、制定和贯彻《关于党内政治生活的若干准则》，端正党风</a></li><li><a href="#二、坚决维护四项基本原则-促进全党在政治上同中央保持一致">二、坚决维护四项基本原则，促进全党在政治上同中央保持一致</a></li><li><a href="#三、平反冤假错案-落实干部政策">三、平反冤假错案，落实干部政策</a></li><li><a href="#四、审查林彪、江青两个反革命集团案件">四、审查林彪、江青两个反革命集团案件</a></li><li><a href="#五、纠正经济领域中的不正之风-打击严重经济犯罪活动">五、纠正经济领域中的不正之风，打击严重经济犯罪活动</a></li></ul></li><li><a href="#纪律检查工作的基本经验">纪律检查工作的基本经验</a><ul><li><a href="#一、执政党的党风问题是有关党的生死存亡的问题">一、执政党的党风问题是有关党的生死存亡的问题</a></li><li><a href="#二、同中央保持一致是党的政治纪律">二、同中央保持一致是党的政治纪律</a></li><li><a href="#三、反腐蚀斗争是整党的重要步骤">三、反腐蚀斗争是整党的重要步骤</a></li></ul></li><li><a href="#今后工作建议">今后工作建议</a><ul><li><a href="#一、各级纪委的主要工作">一、各级纪委的主要工作</a></li><li><a href="#二、加强对纪律检查工作的领导">二、加强对纪律检查工作的领导</a></li><li><a href="#三、进一步提高纪律检查队伍的战斗力">三、进一步提高纪律检查队伍的战斗力</a></li></ul></li></ul></nav><hr><p>  这一届中央纪律检查委员会，是党的十一届三中全会选举产生的。各地区、各部门的纪律检查机构，绝大多数也是三中全会以后逐步重建的。现在，把三年多来的主要工作情况、基本经验和对今后工作的建议，向党的第十二次全国代表大会报告，请予审查。</p><h2 id="三年多来的主要工作" tabindex="-1">三年多来的主要工作 <a class="header-anchor" href="#三年多来的主要工作" aria-label="Permalink to &quot;三年多来的主要工作&quot;">​</a></h2><p>  中央纪律检查委员会，是在十年内乱所造成的党的部分组织和党员思想混乱、党风不正、纪律废弛的情况下成立的。当时面临的主要任务是：在党中央的领导下，采取措施，尽快地把林彪、“四人帮”破坏的党风恢复过来；对大批冤假错案和历史遗留问题，从速加以复查和处理；适应全党工作重点向社会主义现代化建设转移，加强党的战斗力，使党成为领导群众前进的坚强核心，保证党中央路线、方针、政策得到贯彻执行。针对这样的情况，在中央纪委开始工作时，陈云同志就提出：纪律检查委员会的主要工作就是要抓党风。随后又指出：“执政党的党风问题是有关党的生死存亡的问题。”这是纪律检查工作的纲。三年多来，我们在党中央的领导下，紧紧围绕端正党风这个中心，主要做了以下五个方面的工作。</p><h3 id="一、制定和贯彻《关于党内政治生活的若干准则》-端正党风" tabindex="-1">一、制定和贯彻《关于党内政治生活的若干准则》，端正党风 <a class="header-anchor" href="#一、制定和贯彻《关于党内政治生活的若干准则》-端正党风" aria-label="Permalink to &quot;一、制定和贯彻《关于党内政治生活的若干准则》，端正党风&quot;">​</a></h3><p>  《关于党内政治生活的若干准则》，是在中央直接指导下，由中纪委和中央组织部共同起草，又在广泛征求意见加以修改后，经十一届五中全会正式通过的。它是根据我们党几十年来如何增强党性和如何处理党内政治生活的正反两方面经验而制定的。它的制定和执行，是在新的历史条件下，提高党员特别是于部的思想政治水平，增强党性，加强党的建设的一项具有重大意义的措施。三年来的实践证明，这个《准则》起了教育党员，纠正党组织和党员违背党的组织原则的行为的作用，成为端正党风的强有力的武器。各级纪委认真贯彻执行《准则》，把纪律检查工作提高到了一个新的水平。</p><p>  五中全会以后，在各级党委领导下，各级纪委配合有关部门，广泛宣传《准则》，同时采取多种形式，普遍组织党员讨论和学习《中国共产党章程（修改草案）》。一九八〇年，中纪委先后召开了三次贯彻《准则》座谈会，中央批准转发了《第三次贯彻（准则）座谈会纪要》，对推动全党进一步贯彻《准则》起了重要作用。许多地方的党委对照《准则》，进行批评和自我批评，检查党风党纪，纠正不正之风。中纪委和许多地方的纪委，都针对一些倾向性问题，根据《准则》的精神，严肃处理了一批严重破坏党风、违反党纪的案件。凡是贯彻《准则》比较好的地方，党内政治生活逐步恢复正常，健全了组织生活，发扬了民主作风，无政府无组织无纪律现象有所克服。现在，各级纪委正继续努力抓紧《准则》的贯彻执行，使之发挥更大的作用。</p><p>  中纪委还起草了《关于高级干部生活待遇的若干规定》，经中央批准后执行。这对促进党风的好转，改善党和群众的关系，起了良好作用。</p><h3 id="二、坚决维护四项基本原则-促进全党在政治上同中央保持一致" tabindex="-1">二、坚决维护四项基本原则，促进全党在政治上同中央保持一致 <a class="header-anchor" href="#二、坚决维护四项基本原则-促进全党在政治上同中央保持一致" aria-label="Permalink to &quot;二、坚决维护四项基本原则，促进全党在政治上同中央保持一致&quot;">​</a></h3><p>  由于十年内乱的消极后果还没有肃清，党内的“左”倾思想以及极端个人主义思想、无政府主义思想在一部分同志中间还有严重影响，加上近几年来对外交往增多，我们的思想政治工作没有跟上，党内和社会上否定四项基本原则的资产阶级自由化倾向又有所滋长。这就为各级纪委提出了新的任务，必须把维护四项基本原则，加强政治纪律，促进全党在政治上同中央保持一致，放在自己工作的首位。为此，一九七九年和一九八〇年，各级纪委着重对抵制落实干部政策，反对经济调整，反对十一届三中全会路线、方针、政策的案件，进行了检查和处理。一九八一年，各级纪委主要是协助党委，保证中央关于经济上进一步调整，政治上进一步安定的方针的贯彻。在十一届六中全会前后，针对党内和社会上诋毁毛泽东思想，否定毛泽东同志的历史地位，丑化党、反对党的领导的现象，以及一部分人继续宣传毛泽东同志晚年的“左”倾思想，反对三中全会以来的党中央路线的错误言行，进行了两条战线的斗争。同年七月，中央召开思想战线问题座谈会以后，中纪委分别在全国几个地区召开了座谈会，提出要把检查思想政治领域中的问题，维护四项基本原则，作为纪律检查工作的重点，以保证全党在政治上同中央保持一致。</p><h3 id="三、平反冤假错案-落实干部政策" tabindex="-1">三、平反冤假错案，落实干部政策 <a class="header-anchor" href="#三、平反冤假错案-落实干部政策" aria-label="Permalink to &quot;三、平反冤假错案，落实干部政策&quot;">​</a></h3><p>  “文化大革命”和历史上遗留下来的大量冤假错案，严重影响广大干部和群众的积极性。不解决这个重大问题，就无从分清是非，无法恢复党的优良传统和作风，不能巩固安定团结的政治局面。十一届三中全会以前的一段时间，特别是从三中全会开始，党中央直接平反了一批重大的冤假错案，推动了全党这项工作的开展。中纪委在党中央领导下，坚持实事求是的方针，对几件在全党全国有重大影响的案件，进行了复查。</p><p>  对举世瞩目、牵连大批干部和群众的刘少奇同志被定为“叛徒、内奸、工贼”一案，中纪委会同中央组织部，经过大量调查，反复核实材料，证明是一个大冤案，提请党的十一届五中全会做出了平反决议。</p><p>  对所谓瞿秋白同志在一九三五年被国民党逮捕后“自首叛变”的问题，重新作了调查。瞿秋白同志是我们党早期的著名的领导人之一，党内外都很关心他的问题。中央纪律检查委员会经过对他被捕前后的事实调查，证明瞿秋白同志在被捕后坚持了不屈不挠的斗争，因而遭受敌人杀害，为他恢复了名誉。</p><p>  对长期从事党的秘密工作和统战工作的潘汉年同志被定为“内奸”一案，包括许多由此而直接间接被牵连的同志在内，是党的历史上的重大冤案之一。中纪委经过大量复查工作，证明他和其他有关同志根本不是所谓“内奸”，而是对党忠诚，为党的事业作过重要贡献的同志，与有关部门研究后，报经中央批准，已予平反。</p><p>  对一九五九年一批同志被错定为右倾机会主义分子或被错定为犯右倾错误的问题，中纪委进行了复议，提请中央发出通知，做了平反、改正工作。</p><p>  中纪委和各级纪委还对“文化大革命”中的其他大量冤假错案和以前遗留的问题，协同有关部门进行了复查。这些问题的解决，分清了历史是非，调动了广大干部和群众的积极性，增进了党的团结，发扬了党内敢于坚持真理和实事求是的风气。</p><h3 id="四、审查林彪、江青两个反革命集团案件" tabindex="-1">四、审查林彪、江青两个反革命集团案件 <a class="header-anchor" href="#四、审查林彪、江青两个反革命集团案件" aria-label="Permalink to &quot;四、审查林彪、江青两个反革命集团案件&quot;">​</a></h3><p>  在党中央领导下，中纪委和各级纪委会同有关部门，审查了林彪、江青两个反革命集团案件，清查了同此案有牵连的人员。这个案件牵连人数众多，清查工作极其复杂。考虑到“文化大革命”的特定历史条件，中央决定对同两个反革命集团有牵连的人员实行扩大教育面、缩小打击面的政策。这一政策要为广大党员、干部所理解，需要一个教育说服过程。为了贯彻这个政策，各级党委和纪委，在党内外做了大量思想工作。经过反复查证，在贯彻执行党中央的正确方针下，进一步清算了林彪、江青一伙在十年内乱中的罪行，对同两个反革命集团有牵连的人员逐个作出结论。除十名主犯和一批要犯，由法院依法惩处外，对其他犯有严重错误的人，有的分别给了党纪、政纪、军纪处分，有的正在进行处理。</p><p>  康生、谢富治两人，在十年内乱中作恶多端，陷害了大批党政军领导干部和著名民主人士，党内外普遍要求彻底清算他们的罪行。根据中央指示，中纪委对这两人的问题进行了大量调查，根据确凿的材料，作出了结论，报经中央批准，将他们开除出党，并为受他们直接诬陷、迫害的干部恢复了名誉。</p><h3 id="五、纠正经济领域中的不正之风-打击严重经济犯罪活动" tabindex="-1">五、纠正经济领域中的不正之风，打击严重经济犯罪活动 <a class="header-anchor" href="#五、纠正经济领域中的不正之风-打击严重经济犯罪活动" aria-label="Permalink to &quot;五、纠正经济领域中的不正之风，打击严重经济犯罪活动&quot;">​</a></h3><p>  随着党的工作重点的转移，反对经济领域中的不正之风和违法乱纪行为，日益成为一项迫切的斗争。中纪委从一九七九年下半年起，开始提出纠正经济领域中的不正之风。一九八一年，又把它列为端正党风的重点工作之一，先后发了《必须同盗窃国家财产的犯罪行为作坚决斗争》、《关于严肃党纪，杜绝“关系户”不正之风》、《坚决纠正干部队伍中行贿受贿徇私舞弊的歪风》等通告、通报，推动各地开展这方面的斗争。</p><p>  一九八二年一月，中央就打击经济领域中的犯罪活动发出《紧急通知》以后，各级纪委作为党委领导这场斗争的办事机构，全力以赴地抓这项工作，并派出大批干部，协同有关部门，查处一批有党员、干部参与犯罪的大案要案。虽然这场斗争的任务还远没有完成，但已初步打击了经济领域中的严重犯罪活动，歪风邪气有所收敛，广大干部和群众受到了实际的反腐蚀斗争的教育，有利于对外开放、对内搞活经济政策的正确执行。今后，这场斗争还需要继续加强领导，加强清查和打击的力量，进一步深入地开展下去。</p><p>  在上述各项工作的进行过程中，还同时进行了纪律检查机构的组织建设和思想建设，全国县、团级以上党委，除少数企业事业单位外，绝大多数已经建立了纪律检查机构，配备了干部。中央纪委和许多省、市、自治区的党委和纪委，还对纪律检查干部进行了培训。虽然目前各级纪委配备干部的数量质量还与纪委的工作量不尽相称，但已恢复和开展了纪律检查机构的经常工作。一九七九年至一九八一年底，全国纪律检查部门共检查处理现行的违反党纪案件三十五万八千多件，给予党纪处分的党员二十九万五千多人。各级纪委处理群众来信六百五十四万多件，接待来访二百三十多万人次。</p><p>  总的来说，各级纪律检查委员会三年多来做了大量工作，对于促进拨乱反正，恢复和发扬党的优良传统和作风，加强党的建设，保证党的路线、方针、政策的贯彻执行，都起了作用。但是，我们工作的战斗力还很不强，对有些问题的处理表现软弱无力；中纪委对地方各级纪委的工作帮助也很不够，没有担负起双重领导应有的责任。目前纪律检查的工作状况和队伍状况，同所担负的任务都很不适应。需要我们继续努力，提高战斗力，改进工作，更好地完成党交给我们的任务。</p><h2 id="纪律检查工作的基本经验" tabindex="-1">纪律检查工作的基本经验 <a class="header-anchor" href="#纪律检查工作的基本经验" aria-label="Permalink to &quot;纪律检查工作的基本经验&quot;">​</a></h2><p>  过去几年，纪律检查工作是根据中央指示的精神，在吸取历史的经验和研究新情况、新问题的基础上，不断前进的。各级纪委首先要解决的课题，就是在新的历史条件下，究竟如何端正党风，使纪律检查工作有所改进，有所发展，更好地保证党中央的路线、方针、政策的贯彻执行。经过三年多的实践，我们认为以下几个问题是很重要的。</p><h3 id="一、执政党的党风问题是有关党的生死存亡的问题" tabindex="-1">一、执政党的党风问题是有关党的生死存亡的问题 <a class="header-anchor" href="#一、执政党的党风问题是有关党的生死存亡的问题" aria-label="Permalink to &quot;一、执政党的党风问题是有关党的生死存亡的问题&quot;">​</a></h3><p>  我们党在取得全国政权以前，不论在革命战争中，还是在地下斗争和其他形式的斗争中，绝大多数党员经过教育和锻炼，都能自觉地站在斗争的前列，为着革命事业和人民利益，英勇奋斗，流血牺牲。那时候，党和群众的关系非常密切，党在群众中享有很高威信。革命在全国胜利以后，我们党从被压迫、被屠杀、被围剿的地位，转变为领导全国政权的地位，由战争环境转入和平环境。这种根本变化，容易使一些党员、干部产生居功自傲的情绪，贪图享受的情绪。全国解放后入党的有些党员缺乏革命锻炼和党性教育，甚至有少数投机分子混入党内，因而一些党组织就容易失掉革命战斗精神，滋长官僚作风，少数党员往往利用职权谋私利，逐渐脱离实际，脱离群众，在极端的情况下，甚至发展到腐化变质。我们党从七届二中全会以来，就指出存在这种可能性，并且从思想教育和组织上采取了一些防止这种情况发生的措施。在五十年代前期，我们的党风仍然是很好的。但是，后来在“左”倾错误思想影响下，党内政治生活逐渐不正常，民主集中制和实事求是、批评和自我批评等优良作风受到损害。“文化大革命”中，党在思想、政治、组织和作风上受到空前严重的破坏。三中全会以来，由于中央和各级党委的努力，党风已经有了明显的好转。但是，十年内乱遗留下来的党风不正的问题，究竟不是短期内所能完全解决的，而不彻底解决这个问题，党就难以获得广大群众的普遍信任。毫无疑问，我们党一定要，也一定能够完成这个迫切任务，坚决保持党的革命性、战斗性和组织纪律性。正是这种情况和要求，不能不使党的纪律检查工作，从主要处理党员违犯组织纪律案件，发展到着重抓执政党的党风问题。这也是在新的历史条件下，向纪律检查部门提出的新任务。党风不正，就根本谈不上什么党的纪律。</p><p>  执政党的党风问题，说到底，就是我们党能否坚持工人阶级先锋队的性质，保持党和群众的密切联系。党风不正，最大的危险就是脱离群众。广大群众总是直接通过党组织的活动和党员的表现，来看待我们党的。党风的好坏决定人心的向背，而人心的向背又决定着党的命运。十一届三中全会以来，党中央一再强调要端正党风，把它作为加强执政党建设的头等大事。经过全党努力，党风已经有了好转，党的威信有了提高。事实说明，我们党不愧为马克思列宁主义、毛泽东思想武装起来的，经过长期革命斗争考验的无产阶级政党。现在党的队伍的主流仍然是好的，党风正在向好的方向继续发展。对这一点，全党同志必须有正确的认识和坚定的信念。</p><p>  但是，正如胡耀邦同志在这次代表大会上的报告中所说的，必须清醒地看到，目前我们党确实存在思想不纯、作风不纯和组织不纯的问题，党风还没有根本好转。党风没有根本好转，党内政治生活和党的纪律也就不能得到根本改进。当前在少数党员和干部中，不正之风和违法乱纪行为还相当严重，在某些方面还有所发展。此外，还有少数“四人帮”残余势力，继续拉帮结派，兴风作浪。这些严重现象，腐蚀党的肌体，损害党的威信，削弱和破坏党的战斗力，全党同志必须提高认识，坚决对这些严重现象加以制止和克服。</p><p>  整顿党风是整顿机关，整顿企业，整顿社会治安，建设社会主义精神文明的首要环节，我们必须坚持不懈地抓下去。</p><h3 id="二、同中央保持一致是党的政治纪律" tabindex="-1">二、同中央保持一致是党的政治纪律 <a class="header-anchor" href="#二、同中央保持一致是党的政治纪律" aria-label="Permalink to &quot;二、同中央保持一致是党的政治纪律&quot;">​</a></h3><p>  我们要实现社会主义现代化的伟大历史任务，关键是坚持党的领导。党的领导是通过以下几个方面来实现的：一、党中央的正确路线、方针、政策；二、各级党组织坚强的战斗力；三、广大党员的先锋模范作用。有了正确路线，还需要依靠具有坚强战斗力的党组织和党性强、作风好的党员和干部，团结全国各族人民步调一致地去贯彻执行。十一届三中全会确定了马克思主义路线，三年多的实践证明，党中央的领导和路线、方针、政策是正确的，现在的问题是，要保证全党在政治上同中央保持一致，坚决贯彻执行党中央的路线、方针、政策，决不允许各行其是。所有共产党员，尤其是各级领导干部，必须首先严格遵守政治纪律。坚定地在政治上同中央保持一致，这是一条最重要的政治纪律。中央纪律检查委员会明确提出政治纪律，并把维护政治纪律作为重要任务，是有现实意义的。</p><p>  端正党风，需要检查和处理党员在组织上和作风方面违反纪律的问题，但更重要的，必须检查和处理在政治方面违反纪律的问题。违反政治纪律，抵制和反对党中央的路线、方针、政策的贯彻执行，这是危害最大的违犯党纪的现象。</p><p>  当前，对“左”的错误倾向决不能忽视。有些人至今仍然坚持“左”的思想观点，反对十一届三中全会以来的路线、方针、政策，甚至背后串通，两面三刀，制造混乱。这些人的活动，有的地方已经暴露出来了，有的地方因为他们采取两面派手法，或者领导上失去警惕，问题仍然被掩盖着，因而这些人继续占据着领导岗位，这是一大隐患。至于在“文化大革命”中跟随林彪、“四人帮”造反起家的，帮派思想严重的和打砸抢分子，以及反对三中全会以来党中央的路线、方针、政策的人，严重违法乱纪的人。党中央一再强调，必须坚决把他们从领导岗位上撤下来，一个也不能留。凡属严重违反党纪的，必须给以党纪处分；触犯刑律的，必须交给政法部门依法惩处。</p><p>  邓小平同志在一九八〇年十二月中央工作会议上的讲话中强调指出：“各级党组织，每个党员，都要按照党章规定，一切行动服从上级组织的决定，尤其是必须同党中央保持政治上的一致。这一点在现在特别重要。谁违反这一点，谁就要受到党的纪律的处分。党的纪律检查工作要把这一点作为当前的重点。”这就进一步指出了，纪律检查部门必须把维护政治纪律作为自己第一位的工作。</p><p>  保证全党在政治上同中央保持一致，首先要求在坚持四项基本原则这个根本问题上，全党必须完全一致。所有共产党员，只能在言论和行动上坚决拥护，否则，就是离开了党性立场，违背了党章，失掉了共产党员的条件。</p><p>  资产阶级自由化思潮，是“文化大革命”的流毒同资产阶级思想影响相结合的产物。一个时期以来，有人歪曲“解放思想”的口号，公开反对四项基本原则，鼓吹资产阶级的民主和自由，有的共产党员、党的干部公开发表这种宣扬资产阶级自由化的言论。此外，少数党员、干部继续坚持和宣传“左”倾错误的危害，也不能低估。对于这些严重违反党的政治纪律的现象，党的纪律检查部门，今后必须认真地去抓，以保证全党在思想政治上的一致。</p><h3 id="三、反腐蚀斗争是整党的重要步骤" tabindex="-1">三、反腐蚀斗争是整党的重要步骤 <a class="header-anchor" href="#三、反腐蚀斗争是整党的重要步骤" aria-label="Permalink to &quot;三、反腐蚀斗争是整党的重要步骤&quot;">​</a></h3><p>  资本主义思想腐蚀和社会主义思想反腐蚀的斗争，在我国社会主义发展阶段，将不可避免地要长期进行下去。虽然剥削阶级在我国已经消灭，但是阶级斗争仍在一定范围内继续存在，并且在某种条件下还有可能激化。在新的历史条件下，资本主义的腐朽思想和生活方式，也会通过政治、经济、文化等各种渠道，无孔不入地侵入到我们党内来。革命意志不坚定的党员腐化变质的危险性比过去增加了。这种情况，如果任其泛滥，势必严重地腐蚀我们的干部队伍，污染社会风气，破坏安定团结的局面，甚至会毁掉我们经过长期艰苦斗争所取得的一切革命成果。因此，反腐蚀斗争是关系到我们国家盛衰兴亡，关系到我国社会主义现代化建设成败，关系到我们党是否会变颜色的重大问题。我们一定要清醒地看到这种危险性。</p><p>  在新的历史条件下，如何防止党员在资本主义思想腐蚀下腐化变质，已经成为我们执政党建设的重大课题。每个共产党员一定要把抵制资本主义思想的腐蚀，作为对自己最重要的考验。特别是党的领导干部，一定要做一个坚定的、清醒的、有作为的马克思主义者，坚持不懈地把反腐蚀斗争进行到底。</p><p>  目前实行对外开放和对内搞活经济的政策，以加快经济的发展，这是完全正确的，借口某些党员腐化变质而怀疑党的政策的正确性是完全错误的。但是，对于实行对外开放政策以后，可能出现资本主义思想的腐蚀和可能带来的消极后果，我们中纪委也和党的一些其他组织一样，曾经一度认识迟缓，估计不足。直到中央领导同志指出当前资本主义思想腐蚀的严重性和危害性，今年一月中央发出《紧急通知》，提出开展打击经济犯罪活动的斗争，我们才把这个问题提到应有的高度去认识，才大力进行这方面的斗争。</p><p>  目前在全国开展的打击经济领域中严重犯罪活动的斗争，是一场重大的反腐蚀斗争。经过半年多的工作，这场斗争已经取得了初步成效。有些地方，党委加强领导，集中力量，抓住了重点；领导同志亲自动手，分工领导办案；大张旗鼓地处理重大案件，向群众进行反腐蚀斗争的教育，已经积累了一些好的经验。但是，目前还有不少地方和部门仍然领导不力，进展迟缓，阻力很大。我们必须在党中央的领导下，采取坚决有效的措施，迅速改变这种状况。</p><p>  反对资本主义思想腐蚀的斗争，实际上也是对党的作风和组织的整顿，是我们党领导全国人民建设社会主义精神文明和物质文明的重要措施。通过这场斗争，既可以有效地打击犯罪活动，坚决清除腐化变质分子，调整和改组不纯的领导班子，健全党的组织，又能提高广大党员的政治觉悟和抵制腐蚀的能力，保持党的共产主义纯洁性，增强党的战斗力。</p><h2 id="今后工作建议" tabindex="-1">今后工作建议 <a class="header-anchor" href="#今后工作建议" aria-label="Permalink to &quot;今后工作建议&quot;">​</a></h2><p>  党的第十二次代表大会号召全党，为全面开创社会主义现代化建设的新局面而奋斗。各级纪律检查部门和全体纪律检查干部，都要认真学习这次代表大会通过的党中央的报告和新党章，努力工作，保证十二大提出的方针任务的实现。</p><p>  党中央在这次代表大会上所作的报告，提出了有计划、有步骤地进行整党，争取在五年内实现党风根本好转的重要任务。报告和新党章强调新的历史时期党的纪律检查工作的重要地位和作用，对党的纪律检查部门提出了新的更高要求。根据这个精神和当前党风党纪的实际情况，对今后一个时期的纪律检查工作提出以下建议。</p><h3 id="一、各级纪委的主要工作" tabindex="-1">一、各级纪委的主要工作 <a class="header-anchor" href="#一、各级纪委的主要工作" aria-label="Permalink to &quot;一、各级纪委的主要工作&quot;">​</a></h3><p>  十二大以后，在全党结合学习十二大报告和新党章进行思想教育的基础上，有计划、有步骤地整顿党的作风和党的组织，实现党风的根本好转，这是全党的重大任务，也是各级纪委的重大任务。各级纪委要做好各级党委完成这个任务的助手。在党委统一领导下，整顿党的作风和组织，严肃党纪，同党内各种不正之风和违法乱纪行为作斗争，是各级纪委的中心任务。要经常检查各级党组织和党员贯彻执行党章和《关于党内政治生活的若干准则》的情况。</p><p>  维护党的政治纪律，坚持四项基本原则，努力进行以共产主义思想为核心的社会主义精神文明建设，保证全党在政治上同中央保持一致，贯彻执行党中央的路线、方针、政策，是实现党风根本好转的首要问题。各级纪委必须以此作为工作的重点。</p><p>  打击经济领域中严重犯罪活动，是党在今后一个长时期的斗争任务。各级纪委要总结斗争经验，协同有关部门，加强力量，采取有力措施，排除干扰和阻力，继续把这场斗争进行到底。</p><p>  在党委统一领导下，做好整党工作，这不但是纪委今后五年的中心任务，也是今后长期的中心任务。要配合党的组织、宣传等部门，经常注意整顿党的组织，整顿领导班子，坚决清除“三种人”，保持各级党的领导的纯洁性。要协同党的有关部门对全体党员经常进行共产主义思想和党性党风党纪的教育，提高党员的思想觉悟和抵制资本主义思想腐蚀的能力。</p><h3 id="二、加强对纪律检查工作的领导" tabindex="-1">二、加强对纪律检查工作的领导 <a class="header-anchor" href="#二、加强对纪律检查工作的领导" aria-label="Permalink to &quot;二、加强对纪律检查工作的领导&quot;">​</a></h3><p>  要进一步端正党风，必须认真实行各级党委和上级纪委对地方各级纪委的双重领导。为了加强党委对纪委的领导，建议地方各级党委，由一位党委书记或常委担任同级纪委的书记，主管纪律检查工作。</p><p>  各级纪委要对同级党委及其成员实行党章规定范围内的监督。如果发现同级党委或它的成员有违犯党的纪律和国家法律法令的行为，应当如实向同级党委反映，也有权不经过同级党委，直接向上级纪委、上级党委直至党中央反映。对同级党委成员的违纪问题，经同级党委或上级党委、上级纪委同意，必须按照党的原则检查处理。</p><p>  纪委有权检查和处理党的组织和党员违反党的章程、违犯党的纪律和国家法律法令的案件，决定或取消这些案件中对党员的党纪处分；对特别重要或复杂的案件中的问题和处理意见，要向同级党委和上级纪委请示报告。</p><p>  各级纪委必须严格执行民主集中制。纪律检查工作中的重大问题，都要经过领导班子集体讨论作出决定，不能因为少数人有不同意见而久拖不决。任何领导人不能个人说了算，不能个人决定对党员的处分。</p><p>  上级纪委要经常检查和帮助下级纪委的工作，加强具体指导和支持。在政府机关和群众团体中，同级纪委根据工作需要，可以派出纪律检查组或纪律检查员。纪委的常委一般应当是专职的。专职纪委成员，不应随意调动。各级纪委领导干部的任免，要征得上一级纪委的同意。要保持纪律检查干部的相对稳定。</p><h3 id="三、进一步提高纪律检查队伍的战斗力" tabindex="-1">三、进一步提高纪律检查队伍的战斗力 <a class="header-anchor" href="#三、进一步提高纪律检查队伍的战斗力" aria-label="Permalink to &quot;三、进一步提高纪律检查队伍的战斗力&quot;">​</a></h3><p>  在新的历史时期，党的纪律检查工作只能加强，不能削弱。各级纪委要担负起协助党委搞好党风的任务，重要的问题在于加强自身的思想建设和组织建设，提高战斗力。县团级以上单位的党委，没有建立纪律检查机构的，要尽快建立；已经建立的，有些还要适当充实干部力量。公社（乡）和小型企业党委，要设立专职或兼职的纪律检查员。党的总支和支部，要设纪律检查委员。</p><p>  纪律检查机构的组织建设，关键是认真、慎重选拔、任用干部。党的纪律检查干部都应当是：立场坚定，旗帜鲜明；既坚持原则，坚韧不拔，又谦虚谨慎；时刻把党和人民的利益放在心上，勇于负责，敢于斗争，不怕压力，不计较个人得失；严格按照党章和《准则》办事，刚直不阿，不徇私情；廉洁奉公，模范遵守党纪国法。纪委选拔、任用干部，一定要注意保证质量。对不适宜做纪律检查工作的人，要坚决调离。各级纪委的领导班子，必须吸收一定数量的优秀中青年干部参加。</p><p>  要把提高干部的政治素质和业务水平，作为增强纪律检查队伍战斗力的主要环节。对全体纪律检查工作人员，要有计划、有步骤地进行教育和培训。每一个党的纪律检查干部，在工作中都要坚持实事求是的原则，坚持走群众路线。要努力学习党的基本理论和业务知识，切实改进工作方法和工作作风，提高工作效率。</p><p>  党的第十二次全国代表大会以后，我们党的事业将进入一个更加蓬勃发展的新阶段。纪律检查部门担负的责任更重了。党对我们的要求日益提高，广大党员和群众对我们寄予很大希望。各级纪律检查委员会一定要在党中央的领导下，紧紧依靠广大群众，与全党同志团结一致，共同努力，为争取党风的根本好转，把党建设成为领导社会主义现代化事业的坚强核心而奋斗。</p>',67)])])}const u=e(i,[["render",t]]);export{c as __pageData,u as default};
